<template>
  <div class="tab-page"><el-form :inline="true" :model="query" size="small" class="filter-form"><el-form-item label="维护场馆/游戏"><el-input v-model="query.keyword" clearable placeholder="请输入维护场馆名称或游戏名称" /></el-form-item><el-form-item><el-button type="primary" @click="search">筛选</el-button><el-button @click="resetQuery">重置</el-button></el-form-item></el-form><el-table :data="page.rows" border stripe size="mini"><el-table-column type="index" label="序号" width="60" /><el-table-column label="维护场馆" min-width="130"><template slot-scope="s">{{ venueName(s.row.venueId) }}</template></el-table-column><el-table-column label="维护游戏" min-width="130"><template slot-scope="s">{{ gameName(s.row.gameId) }}</template></el-table-column><el-table-column label="维护时间" min-width="250"><template slot-scope="s">{{ s.row.startAt }}{{ s.row.endAt ? ` ~ ${s.row.endAt}` : ' ~ 至今' }}</template></el-table-column><el-table-column prop="operator" label="操作人" width="120" /><el-table-column prop="operatedAt" label="操作时间" width="170" /><el-table-column prop="reason" label="维护原因" min-width="160" /></el-table><pagination v-show="page.total>0" :total="page.total" :page.sync="pageNum" :limit.sync="pageSize" @pagination="syncPage" /></div>
</template>
<script>
const{cloneState,filterMaintenanceLogs,paginate}=require('./model')
export default{name:'MaintenanceLog',props:{state:{type:Object,required:true}},data(){return{query:{keyword:''},appliedQuery:{},pageNum:1,pageSize:10}},computed:{page(){return paginate(filterMaintenanceLogs(this.state.maintenanceLogs,this.state,this.appliedQuery),this.pageNum,this.pageSize)}},methods:{venueName(id){return(this.state.venues.find(v=>v.id===id)||{}).nameZh||'-'},gameName(id){return(this.state.games.find(g=>g.id===id)||{}).name||'-'},search(){this.appliedQuery=cloneState(this.query);this.pageNum=1},resetQuery(){this.query={keyword:''};this.search()},syncPage({page,limit}){this.pageNum=page;this.pageSize=limit}}}
</script>
<style scoped>.filter-form{padding-top:10px}.filter-form .el-input{width:280px}</style>
